#include <bits/stdc++.h>
using namespace std;

struct Node { int id; double x, y; char type; };

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N,K;
    cin>>N>>K;
    vector<Node> nd(N+K);
    for(int i=0;i<N+K;i++) cin>>nd[i].id>>nd[i].x>>nd[i].y>>nd[i].type;

    vector<int> robots, relays;
    for(int i=0;i<N+K;i++){
        if(nd[i].type=='C') relays.push_back(i);
        else robots.push_back(i);
    }

    auto edgeCost=[&](int i,int j)->double{
        if(nd[i].type=='C'&&nd[j].type=='C') return 1e18;
        double dx=nd[i].x-nd[j].x, dy=nd[i].y-nd[j].y;
        double D=dx*dx+dy*dy;
        if(nd[i].type!='C'&&nd[j].type!='C'){
            if(nd[i].type=='S'||nd[j].type=='S') return 0.8*D;
            return D;
        }
        return D;
    };

    // Prim's MST on a set of node indices, returns (cost, parent array, edges)
    auto computeMST=[&](const vector<int>& nodes) -> pair<double, vector<pair<int,int>>> {
        int n=nodes.size();
        vector<double> key(n,1e18);
        vector<int> par(n,-1);
        vector<bool> inM(n,false);
        key[0]=0;
        double total=0;
        for(int iter=0;iter<n;iter++){
            int u=-1;
            for(int i=0;i<n;i++) if(!inM[i]&&(u==-1||key[i]<key[u])) u=i;
            inM[u]=true; total+=key[u];
            for(int v=0;v<n;v++) if(!inM[v]){
                double c=edgeCost(nodes[u],nodes[v]);
                if(c<key[v]){key[v]=c;par[v]=u;}
            }
        }
        vector<pair<int,int>> edges;
        for(int i=1;i<n;i++) edges.push_back({nodes[i],nodes[par[i]]});
        return {total,edges};
    };

    vector<int> active=robots;
    auto [bestCost,bestEdges]=computeMST(active);
    set<int> usedRelays;

    bool improved=true;
    while(improved){
        improved=false;
        int bestR=-1; double bestNewCost=bestCost;
        for(int r:relays){
            if(usedRelays.count(r)) continue;
            vector<int> trial=active; trial.push_back(r);
            auto [c,e]=computeMST(trial);
            if(c<bestNewCost-1e-9){bestNewCost=c;bestR=r;}
        }
        if(bestR>=0){
            usedRelays.insert(bestR);
            active.push_back(bestR);
            auto [c,e]=computeMST(active);
            bestCost=c; bestEdges=e;
            improved=true;
        }
    }

    // Remove degree-1 relays
    bool pruned=true;
    while(pruned){
        pruned=false;
        map<int,int> deg;
        for(auto&[u,v]:bestEdges){deg[u]++;deg[v]++;}
        set<int> toRemove;
        for(int r:usedRelays) if(deg[r]<=1) toRemove.insert(r);
        if(!toRemove.empty()){
            for(int r:toRemove) usedRelays.erase(r);
            active.clear();
            for(int r:robots) active.push_back(r);
            for(int r:usedRelays) active.push_back(r);
            auto [c,e]=computeMST(active);
            bestCost=c; bestEdges=e; pruned=true;
        }
    }

    if(usedRelays.empty()) cout<<"#\n";
    else{bool f=true;for(int c:usedRelays){if(!f)cout<<"#";cout<<nd[c].id;f=false;}cout<<"\n";}
    {bool f=true;for(auto&[u,v]:bestEdges){if(!f)cout<<"#";cout<<nd[u].id<<"-"<<nd[v].id;f=false;}cout<<"\n";}
}
